HERE=Path(__file__).resolve().parent
GUARDS=('source-root-new','source-no-symlink','paths-no-overlap','compile-network-denied','runtime-network-denied','runtime-production-denied','runtime-icloud-denied','runtime-keychain-denied','sdk-read-allowed','artifact-allowlist','runtime-home-isolated','runtime-temp-isolated')
