   recorded_directions={r['name'] for r in recorder.directions}
   for ident,item in recorder.items.items():
    if item['mode']=='cross' and item['metadata']['round']==repeat+1 and item['metadata']['caseID']==case['id'] and 'receipts/'+ident+'-direction.json' not in recorded_directions:
     recorder.direction(ident,'harness-error',[comparison(k,'not-run','dependency-failed') for k in ('entity','array-sequence')])
   def effective(p):
    if capture['fixtureValidity']!='valid' or (case['id'],p['key']) not in verified_round:return False
    if len(p['observations'])!=9 or any(o['rawState']!='schema-valid' for o in p['observations']):return False
    inspected=next(v for v in p['stages'] if v['side']=='go' and v['name']=='cross-inspect')
